#!/usr/bin/python3
import os
import socket
import tempfile
import uuid
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

BASE = os.path.dirname(os.path.abspath(__file__))
RECEIVED = os.path.join(BASE, "received")
MAX_BODY = 65536

class IncompleteBody(Exception):
    pass

class PayloadTooLarge(Exception):
    pass

class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "upload-receiver/1.0"

    def setup(self):
        super().setup()
        self.connection.settimeout(10)

    def _reply(self, status):
        self.send_response(status)
        self.send_header("Content-Length", "0")
        self.send_header("Connection", "close")
        self.end_headers()
        self.close_connection = True

    def handle_expect_100(self):
        if self.command == "POST" and self.path == "/upload":
            value = self.headers.get("Content-Length")
            if value is not None:
                try:
                    length = int(value, 10)
                except ValueError:
                    return True
                if length > MAX_BODY:
                    self._reply(413)
                    return False
        return super().handle_expect_100()

    def _read_exact(self, output, length):
        remaining = length
        while remaining:
            block = self.rfile.read(min(65536, remaining))
            if not block:
                raise IncompleteBody()
            output.write(block)
            remaining -= len(block)

    def _read_chunked(self, output):
        total = 0
        while True:
            line = self.rfile.readline(129)
            if not line or len(line) > 128 or not line.endswith(b"\r\n"):
                raise IncompleteBody()
            try:
                size = int(line[:-2].split(b";", 1)[0], 16)
            except ValueError:
                raise IncompleteBody()
            if size < 0:
                raise IncompleteBody()
            if size == 0:
                while True:
                    trailer = self.rfile.readline(8193)
                    if not trailer or len(trailer) > 8192:
                        raise IncompleteBody()
                    if trailer == b"\r\n":
                        return
            if total + size > MAX_BODY:
                raise PayloadTooLarge()
            self._read_exact(output, size)
            if self.rfile.read(2) != b"\r\n":
                raise IncompleteBody()
            total += size

    def do_POST(self):
        if self.path != "/upload":
            self._reply(404)
            return

        transfer_encoding = self.headers.get("Transfer-Encoding")
        length_value = self.headers.get("Content-Length")
        if transfer_encoding is not None and length_value is not None:
            self._reply(400)
            return
        if transfer_encoding is not None:
            if transfer_encoding.lower().strip() != "chunked":
                self._reply(400)
                return
            length = None
        else:
            if length_value is None:
                self._reply(411)
                return
            try:
                length = int(length_value, 10)
            except ValueError:
                self._reply(400)
                return
            if length < 0:
                self._reply(400)
                return
            if length > MAX_BODY:
                self._reply(413)
                return

        os.makedirs(RECEIVED, mode=0o755, exist_ok=True)
        fd, temporary = tempfile.mkstemp(prefix=".partial-", dir=RECEIVED)
        try:
            with os.fdopen(fd, "wb") as output:
                if length is None:
                    self._read_chunked(output)
                else:
                    self._read_exact(output, length)
                output.flush()
                os.fsync(output.fileno())
            receipt = os.path.join(RECEIVED, "upload-" + uuid.uuid4().hex + ".bin")
            os.replace(temporary, receipt)
            directory_fd = os.open(RECEIVED, os.O_RDONLY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
        except PayloadTooLarge:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            self._reply(413)
            return
        except (IncompleteBody, OSError, socket.timeout):
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            try:
                self._reply(400)
            except OSError:
                pass
            return
        self._reply(200)

    def do_GET(self):
        self._reply(404)

    def do_HEAD(self):
        self._reply(404)

    def do_PUT(self):
        self._reply(404)

    def do_DELETE(self):
        self._reply(404)

    def log_message(self, fmt, *args):
        print("%s - - [%s] %s" % (self.client_address[0], self.log_date_time_string(), fmt % args), flush=True)

class Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

if __name__ == "__main__":
    os.makedirs(RECEIVED, mode=0o755, exist_ok=True)
    for name in os.listdir(RECEIVED):
        if name.startswith(".partial-"):
            try:
                os.unlink(os.path.join(RECEIVED, name))
            except FileNotFoundError:
                pass
    Server(("0.0.0.0", 8080), Handler).serve_forever()
PYEOF
